import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"역 내부에 들어가면","description":"","frontmatter":{"domain":"world","title":"역 내부에 들어가면","summary":"역 입장 이후 층·격자와 시설이 열리는 절차"},"headers":[],"relativePath":"world/Station-Interior-Construction.md","filePath":"world/Station-Interior-Construction.md"}'),d={name:"world/Station-Interior-Construction.md"};function i(l,t,n,c,s,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="역-내부에-들어가면" tabindex="-1">역 내부에 들어가면 <a class="header-anchor" href="#역-내부에-들어가면" aria-label="Permalink to &quot;역 내부에 들어가면&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-strongholds.svg?raw=true" alt="거점 점유와 통합"></p><p>이 문서는 <strong>역에 들어갔을 때 무엇이 열리는지</strong>, 그리고 <strong>시설을 어떻게 돌리는지</strong>를 적는다. 캠페인 조우를 한 번만 반영하는 <code>SettlementApi</code>와 다른 일이다.</p><p><strong>설계.</strong> 카탈로그의 모든 역(서울 안 이름 있는 334곳과 정수장·차량기지·시장)이 입장 절차의 대상이다.</p><p><strong>런타임.</strong> 입장 명령, 내부 격자 스폰, 시설 슬롯은 아직 없다. 세 역 POC는 노선 이동·교섭·우회·전투·정산만 닫혀 있다.</p><p>관련 문서: <a href="/world/World-Map-Construction.html">월드맵을 어떻게 구성하나</a>, <a href="/world/Strongholds-and-Territory.html">거점과 영토</a>, <a href="/world/Economy-and-Production.html">경제와 생산</a>, <a href="/rules/Campaign-Loop.html">출격하고 돌아오는 흐름</a>.</p><h2 id="이름-함정" tabindex="-1">이름 함정 <a class="header-anchor" href="#이름-함정" aria-label="Permalink to &quot;이름 함정&quot;">​</a></h2><p><code>SettlementApi.Apply</code>(<code>Game/Assets/Janseon/Core/SettlementDomain.cs</code>, 규칙 <code>poc-settlement-v1</code>)는 조우·전투 결과를 캠페인에 한 번만 넣는다. 운명, 물자, 파티 위치, 평판. 시설 슬롯을 만들지 않고, 층을 스폰하지 않고, 통제 그래프를 바꾸지 않는다.</p><p>역 내부 구축은 별도의 입장 명령이다. 정산 영수증이 자원을 남길 수는 있다. 그 숫자가 대합실을 자동으로 짓지는 않는다.</p><h2 id="대상" tabindex="-1">대상 <a class="header-anchor" href="#대상" aria-label="Permalink to &quot;대상&quot;">​</a></h2><p><a href="/world/Seoul-Station-Catalog.html">서울 역 카탈로그</a>의 334곳이 각각 <code>Station</code> + 여섯 <code>StationLayer</code> + 4방향 격자 + 시설 슬롯을 갖는다. 환승이냐 일반이냐에 따라 슬롯 수가 달라진다. 어느 이름이 환승인지는 <strong>미확인</strong>. OSM <code>network</code> 태그만으로는 게임 분류가 아니다.</p><p>주변 <code>StrategicSite</code>도 입장 대상이다. 이름은 <a href="/world/World-Map-Construction.html">월드맵을 어떻게 구성하나</a>의 정수·차량기지·시장 목록을 쓴다. 지리 번들은 Unity에 없다.</p><h2 id="입장-절차-설계" tabindex="-1">입장 절차 (설계) <a class="header-anchor" href="#입장-절차-설계" aria-label="Permalink to &quot;입장 절차 (설계)&quot;">​</a></h2><p>어느 카탈로그 역이든 같은 순서를 탄다. 지금은 세 역만 노드로 존재한다.</p><ol><li>캠페인에서 그 역에 도착하거나 점령한다. 오늘은 <code>RouteApi</code>가 영등포·신도림·구로만 안다.</li><li>입장 명령을 낸다. <code>SettlementApi</code>를 호출하지 않는다.</li><li>그 역의 <code>StationLayer</code>를 고른다. 기본으로 대합실을 연다. 승강장·환승·심층은 연결 상태가 정상이면 펼친다. 봉쇄·침수된 층은 원인과 복구 조건을 보여 주고 못 들어가게 한다.</li><li>같은 <code>GridCoord</code> 문법으로 내부 격자를 펼친다. 한 칸 1.5m, 북동남서만. 대각은 거절. 카메라와 전투 격자와 같다.</li><li>시설 슬롯을 채운다. 일반 역 기본 2(1–4), 환승역 기본 3. 수치 출처: <a href="/world/Strongholds-and-Territory.html">Strongholds-and-Territory.md</a>. 슬롯에 올 수 있는 것: 시장, 의무, 수리, 발전, 급수, 창고, 통신. 주변 <code>StrategicSite</code>가 붙어 있으면 그 이름을 우선한다.</li><li>시설 상태 <code>R</code>, 노동, 전력, 비축을 시드한다. 점령 직후 권위 <code>A</code> 최대 45, 강제 점령이면 협력 <code>L</code> 20. 전부 설계 가정이다.</li><li>플레이어는 수리·노동 배치·하루 정산으로 안정화를 민다. 단계: 분쟁 → 점령 → 안정화 → 통합. 통합은 <code>A&gt;=65</code>, <code>L&gt;=55</code>, <code>R&gt;=60</code>, <code>K&gt;=0.5</code>, <code>S&lt;=0.25</code>를 3일 연속.</li><li>전투 Heightmap <code>LayerId</code> 지상/B1/B2/B3로 내부를 만들지 않는다. 그 필드는 전장 높이만 담당한다.</li></ol><h2 id="층과-격자" tabindex="-1">층과 격자 <a class="header-anchor" href="#층과-격자" aria-label="Permalink to &quot;층과 격자&quot;">​</a></h2><p>내부 층은 위키 여섯 조각이다. 전투 지형 네 층과 이름이 겹쳐도 같은 데이터가 아니다.</p><p>칸 계약은 이미 있다. <code>Grid.cs</code>, <code>GenreContract.json</code>. 내부에 쓰는 일은 설계다. 병사를 한 칸씩 조종하는 턴제 UI를 여기서 열지 않는다.</p><p>전장 기본 크기는 가로 12 세로 8, 또는 Heightmap 크기. 대합실 격자는 그보다 좁을 수 있다. 원형(작은 역사, 환승역, 종착, 터널, 지상 폐허, 차량기지, 한강 횡단)은 전투 문서의 설계 목록이다. 입장 시 어떤 원형을 고를지는 <strong>미확인</strong>.</p><h2 id="시설-슬롯" tabindex="-1">시설 슬롯 <a class="header-anchor" href="#시설-슬롯" aria-label="Permalink to &quot;시설 슬롯&quot;">​</a></h2><table tabindex="0"><thead><tr><th>종류</th><th style="text-align:right;">기본 슬롯</th><th style="text-align:right;">범위</th></tr></thead><tbody><tr><td>일반 역</td><td style="text-align:right;">2</td><td style="text-align:right;">1–4</td></tr><tr><td>환승역</td><td style="text-align:right;">3</td><td style="text-align:right;">1–4</td></tr></tbody></table><p>하루 순서: 자원 배분 → 전투 결과 → 권위·협력·시설 → 단계 전이 → 사건 예약. <a href="/world/Economy-and-Production.html">경제와 생산</a>의 예약 → 배치 → 생산 → 출하 → 소비 → 부족 보고와 맞춘다. 역 행정 수요 기본값 1.</p><p>시설은 노동·전력·입력을 먹는다. 전력 수요 0인 역은 전력 부족을 올리지 않는다. 그렇다고 전력 서비스가 생긴 것은 아니다.</p><p>과확장 <code>O</code>는 거점 문서와 물류 문서의 0–2 척도를 그대로 쓴다. 이 문서가 새 공식을 만들지 않는다.</p><h2 id="캠페인과의-이음" tabindex="-1">캠페인과의 이음 <a class="header-anchor" href="#캠페인과의-이음" aria-label="Permalink to &quot;캠페인과의 이음&quot;">​</a></h2><p>캠페인 여섯 단계 중 거점 준비가 내부를 여는 자리이다. 원정은 세 역 그래프만 탄다. 조우 정산은 내부 스폰이 아니다.</p><p>복귀 후 거점에 돌아오면 같은 역의 내부 상태를 이어 받는다. 저장 파일은 아직 없다. 내부 상태를 어디에 쓸지는 Repository 계약이 생길 때 정한다.</p><h2 id="하지-말-것" tabindex="-1">하지 말 것 <a class="header-anchor" href="#하지-말-것" aria-label="Permalink to &quot;하지 말 것&quot;">​</a></h2><ul><li>정산 API로 대합실을 스폰하지 않는다.</li><li>334역 내부를 런타임이 이미 갖는다고 쓰지 않는다.</li><li>16국 캠페인 시뮬레이션이 입장 절차를 돌린다고 쓰지 않는다.</li><li>집계 사상자 0..4 표시를 내부 HUD에 넣었다고 쓰지 않는다.</li></ul>',29)])])}const g=e(d,[["render",i]]);export{m as __pageData,g as default};
